package fr.cercle.tourderole;
import java.util.*;import java.math.*;import java.time.*;
public final class CoreTest{static int checks;static void ok(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}static void rejects(Runnable r,String msg){boolean failed=false;try{r.run();}catch(Exception e){failed=true;}ok(failed,msg);}
public static void main(String[] args){
ok(Core.matches("Étagère entrée boîte bleue","etagere, bleue"),"accent search");ok(!Core.matches("Bleu","bleu rouge"),"all query terms");ok(Core.date("2028-02-29"),"leap");ok(!Core.date("2026-02-29"),"invalid date");ok(Core.nextDate("2026-12-31",1).equals("2027-01-01"),"new year");ok(Core.nextPerson("Alice, Bob, Claire","Bob").equals("Claire"),"rotation");ok(Core.nextPerson("Alice,Bob","Bob").equals("Alice"),"wrap rotation");ok(Core.nextPerson(" ","").isEmpty(),"empty people");
ok(Core.amount("12,50").add(Core.amount("0.1")).compareTo(new BigDecimal("12.60"))==0,"exact money");ok(Core.money(new BigDecimal("-5")).equals("-5.00 €"),"remaining budget");rejects(()->Core.amount("NaN"),"bad amount");long[] d=Core.durations("25:00,05:00,0:01");ok(d.length==3&&d[0]==1500000&&d[2]==1000,"timer sequence");rejects(()->Core.durations("0:00"),"zero timer");rejects(()->Core.durations("1:60"),"seconds bound");rejects(()->Core.durations("-2"),"negative timer");rejects(()->Core.durations("1441:00"),"24h cap");ok(Core.pages("1-3,5,3",10).equals(Arrays.asList(0,1,2,4)),"page order and dedup");rejects(()->Core.pages("0",4),"zero page");rejects(()->Core.pages("4-2",4),"reverse range");rejects(()->Core.pages("5",4),"out of range");ok(Core.hasIngredient("200 g carottes",Arrays.asList("Carotte")),"ingredient presence");ok(!Core.hasIngredient("lait",Arrays.asList("farine")),"missing ingredient");ok(Core.natural("page2.jpg","page10.jpg")<0,"natural comic order");ok(!Core.safeName("../../a/b").contains("..")&&!Core.safeName("../../a/b").contains("/"),"safe filename");long now=1000000;ok(Core.review(now,0,1)==now+600000,"review ten min");ok(Core.review(now,1,10)==now+86400000L,"review tomorrow");ok(Core.review(now,2,3)==now+6*86400000L,"review growth");ok(Core.review(now,2,365)==now+365*86400000L,"review bound");rejects(()->Core.weighted(Arrays.asList(0),new Random(1)),"zero weight");ok(Core.weighted(new ArrayList<>(),new Random(1))==-1,"empty draw");Random rng=new Random(7);int[] counts=new int[2];for(int i=0;i<12000;i++){int p=Core.weighted(Arrays.asList(1,3),rng);ok(p>=0&&p<2,"weighted valid");counts[p]++;}ok(counts[1]>8500&&counts[1]<9500,"weighted distribution");
System.out.println(checks+" domain assertions PASS");}}
